def blueprints(self) -> t.List[str]:
    """The names of the current blueprint upwards through parent
    blueprints.
    """
    if self.blueprint is None:
        return []

    bps: t.List[str] = [self.blueprint]

    while "." in bps[-1]:
        bps.append(bps[-1].rpartition(".")[0])

    return bps

